import Foundation

/// Files created by "New Project". GNU assembler syntax (assembled by clang).
enum Templates {
    static func startup(device: DeviceInfo) -> String {
        var irqVectors = ""
        var irqHandlers = ""
        for i in 0..<32 {
            irqVectors += "    .word IRQ\(i)_Handler\n"
            irqHandlers += "    weak_handler IRQ\(i)_Handler\n"
        }
        return """
        /*
         * startup_\(device.name).s - startup file for \(device.name) (\(device.core))
         * Generated by ARM Sim. GNU assembler syntax.
         *
         * Vector table, Reset_Handler (copies .data, clears .bss, calls main)
         * and weak default handlers that you can override in C,
         * e.g.  void SysTick_Handler(void) { ... }
         */
            .syntax unified
            .thumb

            .section .isr_vector, "a", %progbits
            .align 2
            .global __Vectors
        __Vectors:
            .word __initial_sp          /* Top of Stack (end of IRAM1)  */
            .word Reset_Handler         /* Reset Handler                */
            .word NMI_Handler           /* NMI Handler                  */
            .word HardFault_Handler     /* Hard Fault Handler           */
            .word MemManage_Handler     /* MPU Fault Handler            */
            .word BusFault_Handler      /* Bus Fault Handler            */
            .word UsageFault_Handler    /* Usage Fault Handler          */
            .word 0, 0, 0, 0            /* Reserved                     */
            .word SVC_Handler           /* SVCall Handler               */
            .word DebugMon_Handler      /* Debug Monitor Handler        */
            .word 0                     /* Reserved                     */
            .word PendSV_Handler        /* PendSV Handler               */
            .word SysTick_Handler       /* SysTick Handler              */
            /* External interrupts */
        \(irqVectors)
            .text
            .align 1
            .global Reset_Handler
            .thumb_func
            .type Reset_Handler, %function
        Reset_Handler:
            ldr r1, =__etext            /* copy .data from flash to RAM */
            ldr r2, =__data_start__
            ldr r3, =__data_end__
        1:  cmp r2, r3
            bhs 2f
            ldr r0, [r1]
            adds r1, #4
            str r0, [r2]
            adds r2, #4
            b 1b
        2:  ldr r1, =__bss_start__      /* clear .bss */
            ldr r2, =__bss_end__
            movs r0, #0
        3:  cmp r1, r2
            bhs 4f
            str r0, [r1]
            adds r1, #4
            b 3b
        4:  bl main
            b .
            .ltorg

            .align 1
            .thumb_func
            .type Default_Handler, %function
        Default_Handler:
            b .

            .macro weak_handler name
            .weak \\name
            .thumb_set \\name, Default_Handler
            .endm

            weak_handler NMI_Handler
            weak_handler HardFault_Handler
            weak_handler MemManage_Handler
            weak_handler BusFault_Handler
            weak_handler UsageFault_Handler
            weak_handler SVC_Handler
            weak_handler DebugMon_Handler
            weak_handler PendSV_Handler
            weak_handler SysTick_Handler
        \(irqHandlers)
        """
    }

    static let mainC = """
    /*
     * main.c - example program
     *
     * Open "Debug (printf) Viewer" in debug mode to see the ITM output.
     */
    #include <stdint.h>

    #define SYST_CSR  (*(volatile uint32_t *)0xE000E010)
    #define SYST_RVR  (*(volatile uint32_t *)0xE000E014)
    #define SYST_CVR  (*(volatile uint32_t *)0xE000E018)
    #define ITM_PORT0 (*(volatile uint8_t  *)0xE0000000)

    volatile uint32_t msTicks;

    void SysTick_Handler(void) {
        msTicks++;
    }

    static void print(const char *s) {
        while (*s) ITM_PORT0 = (uint8_t)*s++;
    }

    static void print_uint(uint32_t v) {
        char buf[11];
        int i = 10;
        buf[i] = 0;
        do { buf[--i] = (char)('0' + v % 10u); v /= 10u; } while (v);
        print(&buf[i]);
    }

    static uint32_t fibonacci(uint32_t n) {
        uint32_t a = 0, b = 1;
        while (n--) { uint32_t t = a + b; a = b; b = t; }
        return a;
    }

    int main(void) {
        SYST_RVR = 12000 - 1;          /* 1 ms at 12 MHz */
        SYST_CVR = 0;
        SYST_CSR = 7;                  /* enable, interrupt, core clock */

        print("Hello from ARM Sim!\\n");
        for (uint32_t i = 1; i <= 10; i++) {
            print("fib(");
            print_uint(i);
            print(") = ");
            print_uint(fibonacci(i));
            print("\\n");
        }

        while (1) {
            uint32_t start = msTicks;
            while (msTicks - start < 100) { __asm volatile ("wfi"); }
            print("tick ");
            print_uint(msTicks);
            print("\\n");
        }
    }

    """
}
